<?php require_once __DIR__ . '/../config.php'; require_login(); if(!in_array(role(),['admin','super_admin'],true)) redirect('dashboard.php'); $title='Feedback'; $serviceLabels=['bus_service'=>'Bus service','driver_conductor'=>'Driver or conductor','bus_stand'=>'Bus stand','office_service'=>'Office service','online_service'=>'Online service','other'=>'Other']; include '../includes/header.php'; $rows=$conn->query('SELECT f.*,u.username FROM feedback f LEFT JOIN users u ON u.id=f.user_id ORDER BY f.id DESC'); ?><div class="page"><div class="section-title"><div><h2>Passenger Feedback / මගී ප්‍රතිචාර</h2><p class="muted">Service survey responses and Assistant ratings.</p></div><a class="secondary-btn" href="../dashboard.php">← Dashboard</a></div><div class="table-wrap"><table class="table"><tr><th>Service</th><th>Rating</th><th>Recommend</th><th>Comments</th><th>User</th><th>Service date</th><th>Submitted</th></tr><?php while($x=$rows->fetch_assoc()):?><tr><td><?=h($serviceLabels[$x['service_area']??'']??($x['service_area']??'Assistant'))?></td><td><?=str_repeat('★',(int)$x['rating'])?></td><td><?=h($x['recommend']??'-')?></td><td><?=h($x['note']??'')?></td><td><?=h($x['username']??'Guest')?></td><td><?=h($x['service_date']??'-')?></td><td><?=h($x['created_at'])?></td></tr><?php endwhile;?></table></div></div><?php include '../includes/footer.php'; ?>